$ErrorActionPreference='Stop'
$root='C:\apps\mygermanlingo'
if(-not(Test-Path "$root\frontend\app.js")){throw 'Expected production frontend was not found'}
$files=ConvertFrom-Json '{"portal-polish.css":"","app.js":"","timetable.js":"","index.html":""}'
$names=@('app.js','timetable.js','portal-polish.css','index.html')
$backup=Join-Path $root ('deploy-backups\ce51dad-'+(Get-Date -Format yyyyMMdd-HHmmss))
New-Item -ItemType Directory -Path $backup -Force | Out-Null
foreach($name in $names){Copy-Item -LiteralPath "$root\frontend\$name" -Destination "$backup\$name"}
try {
 foreach($name in $names){
  [IO.File]::WriteAllBytes("$root\frontend\$name.release",[Convert]::FromBase64String($files.$name))
 }
 foreach($name in $names){Move-Item -LiteralPath "$root\frontend\$name.release" -Destination "$root\frontend\$name" -Force}
 $health=Invoke-WebRequest 'http://127.0.0.1:8080/api/health' -UseBasicParsing -TimeoutSec 20
 Write-Output "German Lingo health: $($health.StatusCode)"
 foreach($name in $names){Write-Output "$name $((Get-FileHash -LiteralPath "$root\frontend\$name" -Algorithm SHA256).Hash)"}
 Write-Output "Published ce51dad. Backup: $backup"
} catch {
 foreach($name in $names){Copy-Item -LiteralPath "$backup\$name" -Destination "$root\frontend\$name" -Force}
 throw
}